{
  "architect_scope": "one-R43-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "The champion couples executable continuity to persistent upstream authority, causing an early contract commitment to constrain later cross-objective reconciliation.",
    "causal_change": "Insert one mandatory authority-nullifying executable rebase that preserves the complete policy artifact while extinguishing inherited normative authority before terminal adjudication.",
    "expected_effect": "Separating artifact continuity from authority continuity should let terminal judgment coordinate scan resistance and phase-shift adaptation without inherited commitment inertia.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "mandatory authority-nullifying executable rebase",
    "before": "A contract-locked executable closure transfers persistent conformance authority to a terminal call restricted to behavioral revision.",
    "after": "A complete executable state crosses a mandatory rebase that preserves the artifact but nullifies predecessor authority before terminal holistic adjudication.",
    "why_structural": "The mutation inserts a distinct state transition and changes edge-authority persistence while retaining one sequential, nonbranching executable lineage."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "Executable continuity requires continuity of predecessor authority.",
      "Public-contract conformance must be irreversibly bound before terminal behavioral judgment."
    ],
    "forbidden_inherited_mechanism": "persistent inheritance of an upstream immutable contract lock into terminal behavior-only authority",
    "independent_replacement_principle": "executable continuity with normative-authority discontinuity through an unconditional rebase before terminal adjudication",
    "changed_behavioral_dimensions": [
      "scan-resistance response",
      "phase-shift adaptation"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Authority-Nullifying Executable Rebase",
    "organization": "three-call sequential lineage with one mandatory authority-reset transition",
    "information_flow": "The first call sees all common inputs and emits one complete executable policy state with only provisional commitments. The rebase sees solely that state, preserves its complete executable artifact, and nullifies all inherited normative authority. The terminal call sees the rebased state and public non-anchor evidence, jointly adjudicates conformance and behavior without predecessor authority, and emits one policy.",
    "stages": [
      {
        "id": "authority_discontinuous_lineage",
        "mode": "sequential",
        "calls": [
          {
            "id": "provisional_executable_synthesis",
            "role": "provisional evidence synthesizer",
            "objective": "Form one complete executable policy state from the supplied evidence and expose its contract and behavioral commitments as provisional evidence for mandatory rebasing.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "executable_policy_state"
          },
          {
            "id": "authority_nullifying_rebase",
            "role": "normative-authority reset transition",
            "objective": "Consume provisional_executable_synthesis, preserve its complete executable artifact, extinguish predecessor-granted normative authority, and emit one authority-neutral complete executable policy state.",
            "inputs": [
              "provisional_executable_synthesis"
            ],
            "output_type": "executable_policy_state"
          },
          {
            "id": "independent_terminal_adjudication",
            "role": "independent terminal policy authority",
            "objective": "Consume authority_nullifying_rebase and the supplied public evidence, jointly reconcile public-contract conformance and behavioral evidence without inheriting predecessor commitments, and emit one complete policy.",
            "inputs": [
              "authority_nullifying_rebase",
              "task",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "independent_terminal_adjudication"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
